type Customer = { yearsWithMHPCO: number };
type Item = { type: string };
type Step = { op: "quote"; items: Item[] };
type Scenario = { customer: Customer; steps: Step[] };

type QuoteResult = { premium: number };
type ScenarioResult = { results: QuoteResult[] };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.10;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

const roundUp = (n: number): number => Math.ceil(n - 1e-9);

const sumItemBases = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);

const computePremium = (items: Item[]): number =>
  roundUp(sumItemBases(items) * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: computePremium(step.items) })),
});

