type Customer = { yearsWithMHPCO: number };
type Item = { type: string };
type Step = { op: "quote"; items: Item[] };
type Scenario = { customer: Customer; steps: Step[] };

type QuoteResult = { premium: number };
type ScenarioResult = { results: QuoteResult[] };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_MULTIPLIER = 1.10;
const FLOAT_TOLERANCE = 1e-9;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);

const basePremiumOf = (item: Item): number => BASE_PREMIUM[item.type];

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const sumBasePremiums = (items: Item[]): number => {
  const nonComponents = items.filter((it) => !isComponent(it));
  const components = items.filter(isComponent);
  const nonCompTotal = nonComponents.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const counts = countByType(components);
  let compTotal = 0;
  for (const [type, count] of counts) {
    compTotal += count === BLOCK_SIZE ? BLOCK_PREMIUM : count * BASE_PREMIUM[type];
  }
  return nonCompTotal + compTotal;
};

const computeQuotePremium = (items: Item[]): number =>
  roundUp(sumBasePremiums(items) * FIRST_INSURANCE_MULTIPLIER + PROCESSING_FEE);

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items) })),
});

