import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // === Basics: empty and simplest quotes ===
  it("empty item list → premium 5 G (only processing fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };
    const output = runScenario(scenario);
    expect(output).toEqual({ results: [{ premium: 5 }] });
  });
  it("single sword (steel, ench 3, not cursed), newcomer → premium = 100 base + 10 first + 5 fee = 115 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] }],
    };
    const output = runScenario(scenario);
    expect(output).toEqual({ results: [{ premium: 115 }] });
  });
  it("single amulet (silver, ench 0), newcomer → premium = 60 + 6 + 5 = 71 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 0, cursed: false }] }],
    };
    const output = runScenario(scenario);
    expect(output).toEqual({ results: [{ premium: 71 }] });
  });
  it("single staff (wood, ench 0), newcomer → premium = 80 + 8 + 5 = 93 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff", material: "wood", enchantment: 0, cursed: false }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("single potion, newcomer → premium = 40 + 4 + 5 = 49 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
  });

  // === Components ===
  it("single rune, newcomer → premium = 25 + 3 (rounded up from 2.5) + 5 = 33 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("single moonstone, newcomer → premium = 25 + 3 + 5 = 33 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("2 runes, newcomer → 50 base × 1.10 + 5 fee = 60 G (no block)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes, newcomer → block base 60 × 1.10 + 5 = 71 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    };
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium (7 * 25, no block since 7 not divisible into a group of 3? Wait: spec says 7 runes → 175 G — so no block applies)");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // === Item-specific modifiers ===
  it.todo("cursed sword adds 50% surcharge on that item's base premium");
  it.todo("sword with enchantment exactly 5 → high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");

  // === Policy-wide modifiers ===
  it.todo("customer with exactly 2 years → loyalty discount applies (20%)");
  it.todo("customer with 1 year → no loyalty discount");
  it.todo("first quote in scenario carries first-insurance surcharge (10%)");
  it.todo("second quote in scenario applies follow-up contract discount (15%) and still first-insurance per new item");

  // === Modifier scope on multi-item policies ===
  it.todo("cursed sword + plain amulet, newcomer, first quote → policy base 160, +50 curse, +21 first insurance, +5 fee = 236 G");

  // === Rounding ===
  it.todo("premium yielding 197.5 G → rounded up to 198 G");
  it.todo("payout yielding 350.5 G → rounded down to 350 G");

  // === Claim: standard reimbursement ===
  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 (500 - 100 deductible)");
  it.todo("damage to a rune (value 250), damage 200 → payout 100 (200 - 100 deductible)");

  // === Claim: cap ===
  it.todo("sword insured (sum 1000, cap 2000); two 1500 claims → first payout 1400, remaining cap 600; second payout 600, remaining 0");
  it.todo("cursed sword: cap based on unmodified insurance value → 2000 G");
  it.todo("sword + amulet: insurance sum 1600, cap 3200");
  it.todo("sword + 3 runes (block): insurance sum 1750 (block affects premium only)");

  // === Claim: enchantment threshold ===
  it.todo("steel sword, ench 9, damage 1000 → payout 400 (50% then 100 deductible)");
  it.todo("dragon-material sword, ench 8, damage 1000 → payout 400 (50% wins, then deductible)");
  it.todo("dragon-material sword, ench 9, damage 1000 → payout 400 (both apply, 50% wins)");
  it.todo("dragon-material sword, ench 5, damage 800 → payout 700 (dragon: full, then deductible)");

  // === Claim: deductible per damage event ===
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 (400 + 200, each with own 100 deductible)");

  // === Multiple items of same type ===
  it.todo("policy covers two swords → insurance sum 2000, cap 4000");
  it.todo("dragon attack damages both swords (two entries) → each treated separately with own deductible");
  it.todo("damages array has more entries of a type than the policy covers → CLI exits non-zero, claim rejected");

  // === Integration examples ===
  it.todo("newcomer, 0 years, cursed sword (steel, ench 3) → premium 165 G");
  it.todo("3-year customer, second quote, cursed sword (steel, ench 7) → premium 160 G");

  // === CLI error handling ===
  it.todo("quote with unknown item type → CLI exits non-zero, error to stderr, no results on stdout");
  it.todo("claim references item not in policy → CLI exits non-zero, error to stderr");
  it.todo("claim has damage entry with negative amount → CLI exits non-zero, error to stderr");
});

