export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: QuoteResult[] = [];
  let quoteCount = 0;
  for (const step of scenario.steps) {
    results.push({ premium: computeQuotePremium(step.items, scenario.customer, quoteCount) });
    quoteCount++;
  }
  return { results };
};

